"use client";
import Link from "next/link";
import { BookOpen, Award, ClipboardList, CheckCircle2, ArrowRight, ListChecks } from "lucide-react";
import { useLearnova } from "@/components/LearnovaProvider";
import { DashboardCard, EmptyState, PageHeader, ProgressBar, StatusBadge, LoadingCards } from "@/components/ui";
import CourseCard from "@/components/CourseCard";
import { assignmentFor } from "@/data/learning";
import { certificateEligible, formatDate, progressFor } from "@/lib/learnova-state";

export default function StudentViews({ view = "overview" }: { view?: "overview" | "courses" | "assignments" | "quizzes" | "progress" | "certificates" }) {
  const { state, learner, learning } = useLearnova();
  const enrolled = state.courses.filter(c => !!learning.enrollments[c.id]);
  const completed = enrolled.filter(c => progressFor(c, learning) === 100);
  const certificates = enrolled.filter(c => certificateEligible(c, learning));
  const completedLessons = enrolled.reduce((sum,c)=>sum+c.lessons.filter(l=>learning.enrollments[c.id]?.completed.includes(l.id)).length,0);
  const pendingQuizzes = enrolled.filter(c=>(c.quiz?.length??0)>0&&!learning.quizzes[c.id]).length;
  const pending = enrolled.filter(c => !learning.submissions[c.id]);
  const attempts = Object.values(learning.quizzes);
  const averageQuiz = attempts.length ? Math.round(attempts.reduce((sum, a) => sum + a.score, 0) / attempts.length) : 0;
  const overall = enrolled.length ? Math.round(enrolled.reduce((sum, c) => sum + progressFor(c, learning), 0) / enrolled.length) : 0;
  if (!state.ready) return <LoadingCards />;
  const courseGrid = (items = enrolled) => items.length ? <div className="grid gap-6 md:grid-cols-2 xl:grid-cols-3">{items.map(c => <CourseCard key={c.id} course={c} progress={progressFor(c, learning)} />)}</div> : <EmptyState title="Start your learning journey" description="Enroll in a course to see your lessons and progress here." href="/courses" />;
  const assignmentTable = () => enrolled.length ? <div className="table-wrap"><table className="data-table"><thead><tr><th>Assignment</th><th>Course</th><th>Due date</th><th>Status</th><th>Marks</th><th><span className="sr-only">Actions</span></th></tr></thead><tbody>{enrolled.map(c => { const a = assignmentFor(c); const s = learning.submissions[c.id]; return <tr key={c.id}><td className="font-semibold text-slate-100">{a.title}</td><td>{c.title}</td><td className="whitespace-nowrap">{formatDate(a.due)}</td><td><StatusBadge tone={s?.status === "Graded" ? "green" : s ? "blue" : "amber"}>{s?.status ?? "Pending"}</StatusBadge></td><td>{s?.marks !== undefined ? `${s.marks}/100` : "—"}</td><td><Link href={`/courses/${c.id}/assignment`} className="font-semibold text-blue-400">{s ? "View" : "Submit"}</Link></td></tr>; })}</tbody></table></div> : <EmptyState description="Assignments appear when you enroll in a course." href="/courses" />;
  const quizTable = () => enrolled.length ? <div className="table-wrap"><table className="data-table"><thead><tr><th>Quiz</th><th>Course</th><th>Questions</th><th>Score</th><th>Status</th><th><span className="sr-only">Actions</span></th></tr></thead><tbody>{enrolled.map(c => { const a = learning.quizzes[c.id]; return <tr key={c.id}><td className="font-semibold">{c.title} Knowledge Check</td><td>{c.title}</td><td>{c.quiz?.length ?? 0}</td><td>{a ? `${a.score}%` : "—"}</td><td><StatusBadge tone={a ? a.score >= 70 ? "green" : "amber" : "blue"}>{a ? a.score >= 70 ? "Passed" : "Try again" : "Not started"}</StatusBadge></td><td><Link className="font-semibold text-blue-400" href={`/courses/${c.id}/quiz`}>{a ? "Retake" : "Start Quiz"}</Link></td></tr>; })}</tbody></table></div> : <EmptyState description="Your quizzes will appear here after you enroll." href="/courses" />;
  const progressPanel = () => <div className="panel p-6"><h2 className="section-title">Progress Overview</h2><div className="mt-6 space-y-6"><ProgressBar value={overall} label="Overall learning progress" />{enrolled.map(c => <ProgressBar key={c.id} value={progressFor(c, learning)} label={c.title} />)}</div>{!enrolled.length && <p className="mt-4 text-sm text-slate-400">Enroll in your first course to start tracking progress.</p>}</div>;
  if (view === "courses") return <><PageHeader title="My Courses" description="Your enrolled courses, all in one place." action={<Link href="/courses" className="btn-primary">Explore Courses<ArrowRight size={16} /></Link>} />{courseGrid()}</>;
  if (view === "assignments") return <><PageHeader title="Assignments" description="Keep track of deadlines, submissions, and feedback." />{assignmentTable()}</>;
  if (view === "quizzes") return <><PageHeader title="Quizzes" description="Test your understanding. Score at least 70% to pass." />{quizTable()}</>;
  if (view === "certificates") return <><PageHeader art="certificate" title="Certificates" description="Complete all lessons, pass the quiz, and submit your assignment to earn a certificate." />{certificates.length ? <div className="grid gap-6 md:grid-cols-2">{certificates.map(c => <div className="panel p-7" key={c.id}><Award className="text-blue-400" size={40} /><StatusBadge tone="green">Completed</StatusBadge><h2 className="mt-4 text-xl font-bold">{c.title}</h2><p className="mt-3 text-sm text-slate-400">{learner.name} · {c.instructor}</p><p className="mt-2 text-xs text-slate-400">{formatDate(learning.enrollments[c.id].completedAt ?? learning.quizzes[c.id].date)}</p><Link className="btn-primary mt-5" href={`/courses/${c.id}/certificate`}>View Certificate<ArrowRight size={16} /></Link></div>)}</div> : <EmptyState title="Your achievements belong here" description="Keep learning. Your first certificate is within reach." href="/student-dashboard/courses" action="Continue Learning" />}</>;
  if (view === "progress") return <><PageHeader title="Learning Progress" description="See the skills you are building and the milestones you have reached." /><div className="mb-7 grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><DashboardCard label="Courses Completed" value={completed.length} icon={CheckCircle2} /><DashboardCard label="Courses In Progress" value={enrolled.length - completed.length} icon={BookOpen} /><DashboardCard label="Average Quiz Score" value={`${averageQuiz}%`} icon={ListChecks} /><DashboardCard label="Assignments Completed" value={Object.keys(learning.submissions).length} icon={ClipboardList} /></div>{progressPanel()}<div className="panel mt-6 p-6"><h2 className="section-title">Quiz Performance</h2>{enrolled.filter(c => learning.quizzes[c.id]).map(c => <div className="mt-5" key={c.id}><ProgressBar value={learning.quizzes[c.id].score} label={c.title} /></div>)}{!attempts.length && <p className="mt-4 text-sm text-slate-400">Complete a quiz to see your results here.</p>}</div></>;
  return <><PageHeader art="student" eyebrow="Your learning space" title={`Welcome back, ${learner.name.split(" ")[0]}`} description="A little progress every day adds up. Pick up where you left off." action={<Link className="btn-secondary" href="/courses">Browse Courses</Link>} /><div className="mb-8 grid gap-4 sm:grid-cols-2 xl:grid-cols-3"><DashboardCard label="Enrolled Courses" value={enrolled.length} icon={BookOpen} /><DashboardCard label="Completed Courses" value={completed.length} icon={CheckCircle2} /><DashboardCard label="Completed Lessons" value={completedLessons} icon={CheckCircle2} /><DashboardCard label="Pending Quizzes" value={pendingQuizzes} icon={ListChecks} /><DashboardCard label="Pending Assignments" value={pending.length} icon={ClipboardList} /><DashboardCard label="Certificates" value={certificates.length} icon={Award} /></div><div className="mb-5 flex items-center justify-between"><h2 className="section-title">Continue Learning</h2><Link href="/student-dashboard/courses" className="text-sm font-semibold text-blue-400">View all</Link></div>{courseGrid(enrolled.filter(c => progressFor(c, learning) < 100).slice(0, 3))}<div className="mt-8 grid gap-6 xl:grid-cols-2">{progressPanel()}<div className="panel p-6"><h2 className="section-title">Upcoming Assignments</h2>{pending.map(c => <Link key={c.id} className="mt-5 flex items-center justify-between gap-4 rounded-xl bg-blue-500/5 p-4" href={`/courses/${c.id}/assignment`}><div><p className="text-sm font-semibold">{c.title}: Practical Project</p><p className="mt-2 text-xs text-slate-400">Due {formatDate(assignmentFor(c).due)}</p></div><ArrowRight size={18} className="shrink-0 text-blue-400" /></Link>)}{!pending.length && <p className="mt-5 text-sm text-slate-400">You are up to date. Great work!</p>}</div></div><section className="panel mt-8 p-6"><h2 className="section-title mb-5">Recent activities</h2>{state.activity.length ? state.activity.slice(0,5).map((item,i)=><p className="mt-3 flex gap-3 text-sm leading-7 text-slate-400" key={i}><CheckCircle2 size={16} className="mt-1 shrink-0 text-violet-300"/>{item}</p>):<p className="text-sm text-slate-400">Your next learning milestone will appear here.</p>}</section><div className="mt-8"><h2 className="section-title mb-5">Recent Quiz Results</h2>{quizTable()}</div></>;
}
